import { Client } from "pg";
import { TEST_DATABASE, testDatabaseUrl } from "./db-url";

export default async function setup(): Promise<void> {
  const url = testDatabaseUrl();

  // CREATE DATABASE cannot run inside the database it creates: connect to the
  // server's maintenance database with the same credentials.
  const admin = new URL(url);
  admin.pathname = "/postgres";
  const client = new Client({ connectionString: admin.toString() });
  try {
    await client.connect();
  } catch (cause) {
    throw new Error("database not up: start it with `docker compose up -d db`", { cause });
  }
  try {
    const found = await client.query("SELECT 1 FROM pg_database WHERE datname = $1", [TEST_DATABASE]);
    if (found.rowCount === 0) {
      // The name is the constant above; CREATE DATABASE takes no parameter.
      await client.query("CREATE DATABASE media_test");
    }
  } finally {
    await client.end();
  }

  // Phase 1: run the migrations and the seed against `url` here, and truncate
  // between test files that write (plan §3, "Test database").
}

import { expect, it } from "vitest";
import { Client } from "pg";
import { testDatabaseUrl } from "./db-url";

it("integration tests run against media_test, created by the global setup", async () => {
  const client = new Client({ connectionString: testDatabaseUrl() });
  await client.connect();
  try {
    const { rows } = await client.query("SELECT current_database() AS name");
    expect(rows[0].name).toBe("media_test");
  } finally {
    await client.end();
  }
});

it("refuses a TEST_DATABASE_URL that names another database", () => {
  const saved = process.env.TEST_DATABASE_URL;
  process.env.TEST_DATABASE_URL = "postgres://media:media@localhost:5432/media";
  try {
    expect(() => testDatabaseUrl()).toThrow(/media_test/);
  } finally {
    if (saved === undefined) delete process.env.TEST_DATABASE_URL;
    else process.env.TEST_DATABASE_URL = saved;
  }
});

import { fileURLToPath } from "node:url";
import { defineConfig } from "vitest/config";

const alias = { "@": fileURLToPath(new URL(".", import.meta.url)) };

// Two projects, so unit tests never need the database:
// - unit:        tests/**/*.test.ts(x), no global setup
// - integration: tests/**/*.integration.test.ts, against media_test (tests/global-setup.ts)
export default defineConfig({
  test: {
    projects: [
      {
        resolve: { alias },
        test: {
          name: "unit",
          include: ["tests/**/*.test.{ts,tsx}"],
          exclude: ["tests/**/*.integration.test.ts"],
        },
      },
      {
        resolve: { alias },
        test: {
          name: "integration",
          include: ["tests/**/*.integration.test.ts"],
          globalSetup: ["tests/global-setup.ts"],
          fileParallelism: false,
        },
      },
    ],
  },
});

